"use client";

import { useState, useEffect, useRef } from "react";
import { useAppStore } from "@/store/app-store";
import { apiGet } from "@/lib/api-client";
import { Search, FileText, Heart, Truck, Receipt, X, ArrowRight } from "lucide-react";
import { StatusBadge } from "./status-badge";

type SearchResult = { id: string; title: string; subtitle: string; status: string };
type SearchResults = { requests: SearchResult[]; horses: SearchResult[]; trips: SearchResult[]; invoices: SearchResult[] };

const SECTION_CONFIG: { key: keyof SearchResults; label: string; icon: any; view: string }[] = [
  { key: "requests", label: "Yêu cầu vận chuyển", icon: FileText, view: "request-detail" },
  { key: "horses", label: "Ngựa", icon: Heart, view: "horse-detail" },
  { key: "trips", label: "Chuyến vận chuyển", icon: Truck, view: "trip-detail" },
  { key: "invoices", label: "Hóa đơn", icon: Receipt, view: "invoice-detail" },
];

export function GlobalSearch() {
  const { navigate } = useAppStore();
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResults | null>(null);
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (query.length < 2) { setResults(null); return; }
    setLoading(true);
    const timer = setTimeout(async () => {
      try {
        const data = await apiGet(`/search?q=${encodeURIComponent(query)}`);
        setResults(data.results);
        setOpen(true);
      } catch { /* ignore */ }
      finally { setLoading(false); }
    }, 250);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      // Ctrl+K is handled by the CommandPalette; only handle Escape here
      if (e.key === "Escape") { setOpen(false); inputRef.current?.blur(); }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, []);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const handleResultClick = (view: string, id: string) => {
    navigate(view as any, { id });
    setOpen(false);
    setQuery("");
    setResults(null);
  };

  const totalResults = results ? results.requests.length + results.horses.length + results.trips.length + results.invoices.length : 0;

  return (
    <div ref={containerRef} className="relative hidden md:block">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => query.length >= 2 && setOpen(true)}
          placeholder="Tìm kiếm đơn, ngựa, chuyến, hóa đơn... (Ctrl+K)"
          className="h-9 w-72 rounded-lg border border-border bg-muted/40 pl-9 pr-8 text-sm transition-all placeholder:text-muted-foreground focus:bg-card focus:outline-none focus:ring-2 focus:ring-primary/20 focus:w-80"
        />
        {query && (
          <button onClick={() => { setQuery(""); setResults(null); }} className="absolute right-2 top-1/2 -translate-y-1/2 rounded p-0.5 text-muted-foreground hover:bg-muted">
            <X className="h-3.5 w-3.5" />
          </button>
        )}
      </div>

      {open && (query.length >= 2) && (
        <div className="absolute right-0 top-11 z-50 w-96 overflow-hidden rounded-xl border border-border bg-card shadow-xl animate-fade-in-up">
          <div className="border-b border-border bg-muted/30 px-4 py-2">
            <p className="text-xs font-medium text-muted-foreground">
              {loading ? "Đang tìm..." : `${totalResults} kết quả cho "${query}"`}
            </p>
          </div>
          <div className="max-h-96 overflow-y-auto scrollbar-equideli">
            {!loading && totalResults === 0 ? (
              <div className="flex flex-col items-center justify-center gap-2 py-12 text-muted-foreground">
                <Search className="h-8 w-8 opacity-40" />
                <p className="text-sm">Không tìm thấy kết quả</p>
              </div>
            ) : (
              <div className="divide-y divide-border">
                {SECTION_CONFIG.map((sec) => {
                  const items = results?.[sec.key] || [];
                  if (items.length === 0) return null;
                  const Icon = sec.icon;
                  return (
                    <div key={sec.key}>
                      <div className="sticky top-0 bg-muted/30 px-4 py-1.5">
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{sec.label}</p>
                      </div>
                      {items.map((item) => (
                        <button
                          key={item.id}
                          onClick={() => handleResultClick(sec.view, item.id)}
                          className="flex w-full items-center gap-3 px-4 py-2.5 text-left transition-colors hover:bg-primary/5"
                        >
                          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary">
                            <Icon className="h-4 w-4" />
                          </div>
                          <div className="min-w-0 flex-1">
                            <p className="truncate text-sm font-medium">{item.title}</p>
                            <p className="truncate text-xs text-muted-foreground">{item.subtitle}</p>
                          </div>
                          <StatusBadge status={item.status} />
                          <ArrowRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                        </button>
                      ))}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
