"use client";

import { useAppStore } from "@/store/app-store";
import { ROLE_LABELS, formatDateTime } from "@/lib/constants";
import { apiPost, apiGet } from "@/lib/api-client";
import { Bell, LogOut, Menu, CheckCircle2, AlertTriangle, Truck, ShieldCheck, FileText, Receipt } from "lucide-react";
import { useEffect, useState } from "react";
import { useToast } from "@/hooks/use-toast";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { GlobalSearch } from "./global-search";
import { ThemeToggle } from "./theme-toggle";
import { HelpCircle } from "lucide-react";

const NOTIF_ICONS: Record<string, any> = {
  REQUEST_STATUS: FileText,
  INSPECTION_UPDATE: ShieldCheck,
  PLAN_UPDATE: Truck,
  ASSIGNMENT: Truck,
  INCIDENT_SOS: AlertTriangle,
  INVOICE: Receipt,
  QUARANTINE: ShieldCheck,
  SYSTEM: CheckCircle2,
};

export function AppHeader() {
  const { user, setUser, navigate, view } = useAppStore();
  const [unread, setUnread] = useState(0);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [notifOpen, setNotifOpen] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    if (!user) return;
    let active = true;
    (async () => {
      try {
        const data = await apiGet("/notifications");
        if (active) {
          setNotifications(data.notifications);
          setUnread(data.notifications.filter((n: any) => !n.isRead).length);
        }
      } catch { /* ignore */ }
    })();
    return () => { active = false; };
  }, [user, view]);

  const handleLogout = async () => {
    try {
      await apiPost("/auth/logout");
      setUser(null);
      toast({ title: "Đã đăng xuất", description: "Hẹn gặp lại." });
    } catch {
      setUser(null);
    }
  };

  const handleNotifClick = async (n: any) => {
    if (!n.isRead) {
      try {
        await apiPost("/notifications", { notificationId: n.notificationId });
        setUnread((u) => Math.max(0, u - 1));
        setNotifications((prev) => prev.map((x) => x.notificationId === n.notificationId ? { ...x, isRead: true } : x));
      } catch { /* ignore */ }
    }
    setNotifOpen(false);
    if (n.relatedEntityType === "transport_requests") navigate("request-detail", { id: n.relatedEntityId });
    else if (n.relatedEntityType === "transport_plans") navigate("trip-detail", { id: n.relatedEntityId });
    else if (n.relatedEntityType === "invoices") navigate("invoice-detail", { id: n.relatedEntityId });
    else navigate("notifications");
  };

  const handleMarkAllRead = async () => {
    const unreadNotifs = notifications.filter((n) => !n.isRead);
    for (const n of unreadNotifs) {
      try { await apiPost("/notifications", { notificationId: n.notificationId }); } catch { /* ignore */ }
    }
    setNotifications((prev) => prev.map((x) => ({ ...x, isRead: true })));
    setUnread(0);
    toast({ title: "Đã đánh dấu tất cả là đã đọc" });
  };

  if (!user) return null;
  const initials = user.name.split(" ").map((w) => w[0]).slice(0, 2).join("");

  return (
    <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-border bg-card/80 px-4 backdrop-blur-md sm:px-6">
      <div className="flex flex-1 items-center gap-3">
        <button
          className="flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted lg:hidden"
          onClick={() => useAppStore.getState().setSidebarOpen(!useAppStore.getState().sidebarOpen)}
        >
          <Menu className="h-5 w-5" />
        </button>
        <div className="hidden sm:block">
          <p className="text-xs text-muted-foreground">Xin chào,</p>
          <p className="text-sm font-semibold leading-tight">{user.name}</p>
        </div>
        <div className="ml-auto">
          <GlobalSearch />
        </div>
      </div>

      <div className="flex items-center gap-2">
        <ThemeToggle />
        <button
          onClick={() => { window.dispatchEvent(new KeyboardEvent("keydown", { key: "?" })); }}
          className="flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted transition-colors"
          aria-label="Phím tắt"
          title="Phím tắt (?)"
        >
          <HelpCircle className="h-5 w-5" />
        </button>
        {/* Notifications dropdown */}
        <DropdownMenu open={notifOpen} onOpenChange={setNotifOpen}>
          <DropdownMenuTrigger asChild>
            <button
              className="relative flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-muted transition-colors"
              aria-label="Thông báo"
            >
              <Bell className="h-5 w-5" />
              {unread > 0 && (
                <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 animate-pulse-soft items-center justify-center rounded-full bg-[var(--danger)] px-1 text-[10px] font-bold text-white">
                  {unread}
                </span>
              )}
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-80 p-0 sm:w-96">
            <div className="flex items-center justify-between border-b border-border px-4 py-3">
              <div>
                <p className="text-sm font-semibold">Thông báo</p>
                <p className="text-xs text-muted-foreground">{unread} chưa đọc</p>
              </div>
              {unread > 0 && (
                <button onClick={handleMarkAllRead} className="text-xs font-medium text-primary hover:underline">
                  Đánh dấu tất cả đã đọc
                </button>
              )}
            </div>
            <ScrollArea className="max-h-96">
              {notifications.length === 0 ? (
                <div className="flex flex-col items-center justify-center gap-2 py-12 text-muted-foreground">
                  <Bell className="h-8 w-8 opacity-40" />
                  <p className="text-sm">Không có thông báo</p>
                </div>
              ) : (
                <div className="divide-y divide-border">
                  {notifications.slice(0, 10).map((n) => {
                    const Icon = NOTIF_ICONS[n.type] || CheckCircle2;
                    const isSos = n.type === "INCIDENT_SOS";
                    return (
                      <button
                        key={n.notificationId}
                        onClick={() => handleNotifClick(n)}
                        className={`flex w-full items-start gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/50 ${!n.isRead ? "bg-primary/5" : ""}`}
                      >
                        <div className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${isSos ? "bg-[var(--danger)] text-white" : !n.isRead ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground"}`}>
                          <Icon className="h-4 w-4" />
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <p className={`truncate text-sm ${!n.isRead ? "font-semibold" : "font-medium"}`}>{n.title}</p>
                            {!n.isRead && <span className="h-2 w-2 shrink-0 rounded-full bg-primary" />}
                          </div>
                          <p className="mt-0.5 text-xs text-muted-foreground line-clamp-2">{n.message}</p>
                          <p className="mt-1 text-[10px] text-muted-foreground">{formatDateTime(n.createdAt)}</p>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </ScrollArea>
            <div className="border-t border-border p-2">
              <button onClick={() => { setNotifOpen(false); navigate("notifications"); }} className="w-full rounded-lg py-2 text-center text-sm font-medium text-primary hover:bg-primary/5">
                Xem tất cả thông báo
              </button>
            </div>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button className="flex items-center gap-2 rounded-lg p-1 pr-2 hover:bg-muted transition-colors">
              <Avatar className="h-8 w-8 border border-border">
                <AvatarFallback className="bg-primary/10 text-xs font-bold text-primary">{initials}</AvatarFallback>
              </Avatar>
              <div className="hidden text-left sm:block">
                <p className="text-xs font-medium leading-tight">{user.name}</p>
                <p className="text-[10px] text-muted-foreground leading-tight">{ROLE_LABELS[user.roleId]}</p>
              </div>
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-56">
            <DropdownMenuLabel>
              <p className="font-semibold">{user.name}</p>
              <p className="text-xs font-normal text-muted-foreground">{user.email}</p>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem className="gap-2">
              <Badge variant="outline" className="bg-primary/5">{ROLE_LABELS[user.roleId]}</Badge>
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={handleLogout} className="gap-2 text-[var(--danger-fg)] focus:text-[var(--danger-fg)]">
              <LogOut className="h-4 w-4" /> Đăng xuất
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}
